<?php
declare(strict_types=1);
require_once dirname(__DIR__, 2) . '/classes/GreenPortalDatabase.php';
require_once dirname(__DIR__, 2) . '/classes/PermissaoTransacao.php';
require_once dirname(__DIR__, 2) . '/classes/UsuarioSessao.php';
require_once dirname(__DIR__, 2) . '/classes/TenantContext.php';
require_once dirname(__DIR__, 2) . '/classes/IdiomaService.php';
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
header('Content-Type: application/json; charset=utf-8');
$fail = static function (string $message, int $status = 400): never { http_response_code($status); echo json_encode(['ok'=>false,'message'=>$message], JSON_UNESCAPED_UNICODE); exit; };
if (empty($_SESSION['autenticado']) || empty($_SESSION['tenant']['banco_dados'])) $fail(IdiomaService::t('comum.erro.sessao', ['pt' => 'Sua sessão expirou. Entre novamente no portal.', 'en' => 'Your session has expired. Please sign in again.', 'es' => 'Su sesión expiró. Vuelva a entrar al portal.']), 401);
$documentId = max(0, (int)($_POST['coddocumento'] ?? $_GET['coddocumento'] ?? 0)); if ($documentId < 1) $fail(IdiomaService::t('modulolegal_controle.erro.documento', ['pt' => 'Documento inválido.', 'en' => 'Invalid document.', 'es' => 'Documento inválido.']));
try {
$env = GreenPortalDatabase::env(); $tenant = TenantContext::connect($env, $_SESSION);
if (!UsuarioSessao::atualizar($tenant, $_SESSION)) $fail(IdiomaService::t('comum.erro.sessao', ['pt' => 'Sua sessão expirou. Entre novamente no portal.', 'en' => 'Your session has expired. Please sign in again.', 'es' => 'Su sesión expiró. Vuelva a entrar al portal.']), 401);
$permission = PermissaoTransacao::obter('CONTROLE_DOCUMENTOS'); if (!$permission['pode_visualizar']) $fail(IdiomaService::t('modulolegal_controle.resp.erro_ver', ['pt' => 'Sem permissão para visualizar responsáveis.', 'en' => 'You are not allowed to view responsible parties.', 'es' => 'Sin permiso para ver los responsables.']), 403);
$call = static fn(string $procedure, array $params = []): array => GreenPortalDatabase::call($tenant, $procedure, $params);
$json = static fn(mixed $value): string => json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
$doc = $call('CALL sp_crud_select(:tabela,:filtros,NULL,1,0)', ['tabela'=>'documentos','filtros'=>$json(['CODDOCUMENTO'=>$documentId])]); if (!$doc) $fail(IdiomaService::t('modulolegal_controle.erro.documento_nao_localizado', ['pt' => 'Documento não localizado.', 'en' => 'Document not found.', 'es' => 'Documento no encontrado.']), 404);
$module = $call('CALL sp_crud_select(:tabela,:filtros,NULL,1,0)', ['tabela'=>'responsabilidade_modulos','filtros'=>$json(['CODIGO'=>'CONTROLE'])]); $moduleId=(int)($module[0]['CODMODULO']??0); if(!$moduleId)$fail(IdiomaService::t('modulolegal_controle.resp.erro_modulo', ['pt' => 'Módulo de responsabilidades não configurado.', 'en' => 'Responsibility module not configured.', 'es' => 'Módulo de responsabilidades no configurado.']),500);
$type = $call('CALL sp_crud_select(:tabela,:filtros,NULL,1,0)', ['tabela'=>'vw_responsabilidade_tipos','filtros'=>$json(['MODULO_CODIGO'=>'CONTROLE','ATIVO'=>1])]); $typeId=(int)($type[0]['CODTIPORESPONSABILIDADE']??0); if(!$typeId)$fail(IdiomaService::t('modulolegal_controle.resp.erro_tipo', ['pt' => 'Tipo de responsabilidade não configurado.', 'en' => 'Responsibility type not configured.', 'es' => 'Tipo de responsabilidad no configurado.']),500);
$list = static function () use ($call,$json,$documentId): array { return $call('CALL sp_crud_select(:tabela,:filtros,NULL,1000,0)', ['tabela'=>'vw_responsabilidade_controle_documentos','filtros'=>$json(['CODDOCUMENTO'=>$documentId])]); };
$action = strtolower(trim((string)($_POST['action'] ?? $_GET['action'] ?? 'list')));
$respond = static function (array $rows, array $users, array $groups, int $typeId, array $permission): never { echo json_encode(['ok'=>true,'title'=>IdiomaService::t('modulolegal_controle.resp.titulo', ['pt' => 'Responsáveis', 'en' => 'Responsible parties', 'es' => 'Responsables']),'rows'=>$rows,'users'=>array_map(static fn(array $r):array=>['id'=>(int)$r['CODUSUARIO'],'label'=>trim((string)($r['NOME']??''))?:((string)($r['USERID']??''))],$users),'groups'=>array_map(static fn(array $r):array=>['id'=>(int)$r['CODGRUPO'],'label'=>(string)$r['NOME']],$groups),'type_id'=>$typeId,'can_edit'=>(bool)$permission['pode_editar'],'can_add'=>(bool)$permission['pode_incluir'],'can_delete'=>(bool)$permission['pode_excluir']],JSON_UNESCAPED_UNICODE); exit; };
$users=$call('CALL sp_crud_select(:tabela,:filtros,NULL,10000,0)',['tabela'=>'vw_responsabilidade_usuarios_ativos','filtros'=>'{}']); $groups=$call('CALL sp_crud_select(:tabela,:filtros,NULL,10000,0)',['tabela'=>'vw_responsabilidade_grupos_ativos','filtros'=>'{}']);
if($action==='list') $respond($list(),$users,$groups,$typeId,$permission);
if($action!=='sync'||($_SERVER['REQUEST_METHOD']??'GET')!=='POST')$fail(IdiomaService::t('comum.erro.acao_invalida', ['pt' => 'Ação inválida.', 'en' => 'Invalid action.', 'es' => 'Acción inválida.']));
if(!$permission['pode_editar']&&!$permission['pode_incluir']&&!$permission['pode_excluir'])$fail(IdiomaService::t('modulolegal_controle.resp.erro_alterar', ['pt' => 'Sem permissão para alterar responsáveis.', 'en' => 'You are not allowed to change responsible parties.', 'es' => 'Sin permiso para modificar los responsables.']),403);
$posted=json_decode((string)($_POST['responsibilities']??'[]'),true); if(!is_array($posted))$fail(IdiomaService::t('modulolegal_controle.resp.erro_lista', ['pt' => 'Lista de responsáveis inválida.', 'en' => 'Invalid list of responsible parties.', 'es' => 'Lista de responsables inválida.']));
$current=$list(); $keep=[]; foreach($posted as $item){$id=(int)($item['id']??0); if($id>0)$keep[$id]=true;}
if(!$permission['pode_excluir'])foreach($current as $row)if(!isset($keep[(int)$row['CODATRIBUICAO']]))$fail(IdiomaService::t('modulolegal_controle.resp.erro_remover', ['pt' => 'Sem permissão para remover responsáveis.', 'en' => 'You are not allowed to remove responsible parties.', 'es' => 'Sin permiso para quitar responsables.']),403);
foreach($current as $row){$id=(int)$row['CODATRIBUICAO'];if(!isset($keep[$id]))$call('CALL sp_crud_update(:tabela,:chave,:dados)',['tabela'=>'responsabilidade_atribuicoes','chave'=>$json(['CODATRIBUICAO'=>$id]),'dados'=>$json(['ATIVO'=>0,'CODUSUARIOALTERACAO'=>(int)$_SESSION['usuario']['codusuario']])]);}
foreach($posted as $item){$id=(int)($item['id']??0);if($id>0)continue;if(!$permission['pode_incluir'])$fail(IdiomaService::t('modulolegal_controle.resp.erro_incluir', ['pt' => 'Sem permissão para incluir responsáveis.', 'en' => 'You are not allowed to add responsible parties.', 'es' => 'Sin permiso para agregar responsables.']),403);$dest=strtoupper(trim((string)($item['tipo_destino']??'')));$uid=$dest==='USUARIO'?max(0,(int)($item['codusuario']??0)):null;$gid=$dest==='GRUPO'?max(0,(int)($item['codgrupo']??0)):null;$data=['CODMODULO'=>$moduleId,'ORIGEM'=>'DIRETA','CODTIPORESPONSABILIDADE'=>$typeId,'ENTIDADE'=>'documentos','REGISTRO_ID'=>(string)$documentId,'TIPO_DESTINO'=>$dest,'CODUSUARIO'=>$uid,'CODGRUPO'=>$gid,'PRIORIDADE'=>(int)($item['prioridade']??0),'PRINCIPAL'=>!empty($item['principal'])?1:0,'VALIDO_DE'=>trim((string)($item['valido_de']??date('Y-m-d'))),'VALIDO_ATE'=>trim((string)($item['valido_ate']??''))?:null,'OBSERVACAO'=>trim((string)($item['observacao']??'')),'ATIVO'=>1,'CODUSUARIOALTERACAO'=>(int)$_SESSION['usuario']['codusuario']];$call('CALL sp_responsabilidade_validar_duplicidade(NULL,:modulo,:origem,:tipo,NULL,:entidade,:registro,:destino,:usuario,:grupo,:de,:ate)',['modulo'=>$moduleId,'origem'=>'DIRETA','tipo'=>$typeId,'entidade'=>'documentos','registro'=>(string)$documentId,'destino'=>$dest,'usuario'=>$uid,'grupo'=>$gid,'de'=>$data['VALIDO_DE'],'ate'=>$data['VALIDO_ATE']]);$call('CALL sp_crud_insert(:tabela,:dados)',['tabela'=>'responsabilidade_atribuicoes','dados'=>$json($data)]);}
$respond($list(),$users,$groups,$typeId,$permission);
} catch (Throwable $erro) {
    // Aviso de procedure (ex.: vínculo com vigência sobreposta) ou falha de banco: mensagem no idioma do usuário.
    error_log('controle_documentos_responsabilidades: ' . $erro->getMessage());
    $fail(IdiomaService::erro($erro, 'salvar'), 422);
}
